'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var isArray = require( '@stdlib/assert/is-array' );
var hasProp = require( '@stdlib/assert/has-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var inherit = require( '@stdlib/utils/inherit' );
var DiscretizingScale = require( '@stdlib/plot/vega/scale/discretizing' );
var format = require( '@stdlib/string/format' );
var TYPE = require( './type/type.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getDomain = require( './domain/get.js' );
var setDomain = require( './domain/set.js' );

var getRange = require( './range/get.js' );
var setRange = require( './range/set.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );


// MAIN //

/**
* Threshold scale constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.name - scale name
* @param {Array} [options.domain] - domain of associated data values
* @param {number} [options.domainMax] - maximum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMin] - minimum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMid] - single mid-point value inserted into a two-element domain
* @param {Collection} [options.domainRaw] - array of raw domain values which overrides the `domain` property
* @param {(string|Object)} [options.interpolate] - scale range interpolation method
* @param {Array} [options.range] - scale range
* @param {boolean} [options.reverse=false] - boolean indicating whether to reverse the order of the scale range
* @param {boolean} [options.round=false] - boolean indicating whether to round numeric output values to integers
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {ThresholdScale} scale instance
*
* @example
* var scale = new ThresholdScale({
*     'name': 'colorScale',
*     'domain': [ 1, 2 ],
*     'range': [ 1, 2, 3 ]
* });
* // returns <ThresholdScale>
*/
function ThresholdScale( options ) {
	if ( !( this instanceof ThresholdScale ) ) {
		return new ThresholdScale( options );
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasProp( options, 'type' ) && options.type !== TYPE ) {
		throw new TypeError( format( 'invalid argument. `%s` option must be equal to "%s". Option: `%s`.', 'type', TYPE, options.type ) );
	}
	if ( hasProp( options, 'domain' ) && !isArray( options.domain ) ) {
		throw new TypeError( format( 'invalid argument. `%s` option must be an array. Option: `%s`.', 'domain', options.domain ) );
	}
	if ( hasProp( options, 'range' ) && !isArray( options.range ) ) {
		throw new TypeError( format( 'invalid argument. `%s` option must be an array. Option: `%s`.', 'range', options.range ) );
	}
	if ( options.range.length !== options.domain.length + 1 ) {
		throw new TypeError( format( 'invalid assignment. `%s` length must be exactly one greater than `%s` length. %s length: `%u`. %s length: `%u`.', 'range', 'domain', 'range', options.range.length, 'domain', options.domain.length ) );
	}
	DiscretizingScale.call( this, options );
	this._type = TYPE;
	return this;
}

/*
* Inherit from a parent prototype.
*/
inherit( ThresholdScale, DiscretizingScale );

/**
* Constructor name.
*
* @private
* @name name
* @memberof ThresholdScale
* @readonly
* @type {string}
*/
setReadOnly( ThresholdScale, 'name', 'ThresholdScale' );

/**
* Scale domain.
*
* @name domain
* @memberof ThresholdScale.prototype
* @type {(Array|void)}
*
* @example
* var scale = new ThresholdScale({
*     'name': 'colorScale',
*     'domain': [ 0, 1 ],
*     'range': [ 'blue', 'white', 'red' ]
* });
*
* var v = scale.domain;
* // returns [ 0, 1 ]
*/
setReadWriteAccessor( ThresholdScale.prototype, 'domain', getDomain, setDomain );

/**
* Scale range.
*
* @name range
* @memberof ThresholdScale.prototype
* @type {(Array|void)}
*
* @example
* var scale = new ThresholdScale({
*     'name': 'colorScale',
*     'domain': [ 0, 1 ],
*     'range': [ 'blue', 'white', 'red' ]
* });
*
* var v = scale.range;
* // returns [ 'blue', 'white', 'red' ]
*/
setReadWriteAccessor( ThresholdScale.prototype, 'range', getRange, setRange );

/**
* Scale type.
*
* @name type
* @memberof ThresholdScale.prototype
* @type {string}
* @default 'threshold'
*
* @example
* var scale = new ThresholdScale({
*     'name': 'colorScale',
*     'domain': [ 1, 2 ],
*     'range': [ 1, 2, 3 ]
* });
*
* var v = scale.type;
* // returns 'threshold'
*/
setReadWriteAccessor( ThresholdScale.prototype, 'type', getType, setType );


// EXPORTS //

module.exports = ThresholdScale;
